const enabled = String($env.INFLUENCER_INTELLIGENCE_ENABLED || 'false').trim().toLowerCase() === 'true';
const serviceUrl = String($env.INFLUENCER_INTELLIGENCE_SERVICE_URL || '').trim();
if (enabled && !/^https?:\/\/(127\.0\.0\.1|localhost|[a-z0-9.-]+\.internal)(?::\d+)?(?:\/|$)/i.test(serviceUrl)) {
  throw new Error('INFLUENCER_INTELLIGENCE_SERVICE_URL must resolve to an internal service');
}
return [{ json: {
  enabled,
  status: enabled ? 'enabled' : 'disabled',
  reason: enabled ? null : 'feature_flag_off',
  workflow_version: 'influencer-intelligence-snapshot-workflow/v1',
  mode: enabled ? 'shadow' : 'off',
  requested_at: new Date().toISOString()
} }];

const rows = $input.all().map((item) => item.json || {}).slice(0, 25);
const creators = rows.map((row) => ({
  creator_key: String(row.creator_key || '').trim(),
  identity_key: String(row.identity_key || '').trim(),
  canonical_handle: row.canonical_handle ? String(row.canonical_handle).trim() : null,
  provider: String(row.provider || '').trim(),
  operations: ['snapshot_creator', 'snapshot_creator_media'],
  bucket_seconds: 3600,
  media_limit: 20
})).filter((creator) => creator.creator_key && creator.identity_key && ['meta-graph', 'instagrapi'].includes(creator.provider));
return [{ json: {
  contract_version: 'influencer-intelligence/scheduler/v1',
  workflow_version: 'influencer-intelligence-snapshot-workflow/v1',
  mode: 'shadow',
  max_creators: 25,
  max_concurrency: 1,
  timeout_ms: 30000,
  retry_policy: {
    max_attempts: 2,
    same_idempotency_key: true,
    retryable_classes: ['timeout', 'rate_limited', 'upstream_5xx', 'network_transient']
  },
  service_path: '/internal/influencer-intelligence/v1/snapshots',
  creators
} }];

const response = $input.first()?.json || {};
const coverage = response.coverage && typeof response.coverage === 'object' ? response.coverage : { state: 'unavailable', available: null, expected: null, ratio: null };
const failures = Array.isArray(response.failures) ? response.failures.slice(0, 50).map((failure) => ({ code: String(failure.code || 'provider_failure').slice(0, 80), classification: String(failure.classification || 'permanent').slice(0, 40), retryable: failure.retryable === true })) : [];
return [{ json: {
  event_type: 'snapshot_result_registered',
  event_version: 'influencer-intelligence/snapshot-result/v1',
  status: String(response.status || response.collectorRun?.status || 'failed'),
  coverage,
  freshness: response.freshness || { status: 'unknown', observedAt: null, retrievedAt: null, ageSeconds: null },
  failure_count: failures.length,
  failures,
  deduplicated: response.deduplicated === true,
  no_provider_payload_logged: true,
  no_credentials_logged: true
} }];

const raw = $input.first()?.json || {};
const error = raw.error || {};
const message = String(error.message || 'workflow_failure').replace(/(authorization|token|api[_-]?key|secret|cookie|password)\s*[:=]\s*[^\s,\"'}]+/ig, '$1=[REDACTED]').slice(0, 500);
return [{ json: { event_type: 'snapshot_scheduler_failure', event_version: 'influencer-intelligence/snapshot-result/v1', status: 'failed', code: String(error.code || 'workflow_failure').slice(0, 80), message, retry_policy: { bounded: true, same_idempotency_key_required: true } } }];
